const body = $json.body ?? $json;
const required = ['event_id','tenant_id','product','status'];
const missing = required.filter((key) => !body[key]);
if (missing.length) {
  throw new Error('tenant.provisioned missing fields: ' + missing.join(', '));
}
return [{json:{
  event_id:String(body.event_id),
  event_type:'tenant.provisioned',
  tenant_id:String(body.tenant_id),
  product:String(body.product),
  status:String(body.status),
  tenant_url:body.tenant_url ?? null,
  admin_url:body.admin_url ?? null,
  company_id:body.company_id ?? null,
  license_id:body.license_id ?? null,
  occurred_at:body.occurred_at ?? new Date().toISOString(),
  idempotency_key:String(body.event_id)
}}];
